import re
def parse(md):
    out={}; cur=None
    for block in re.split(r'\n### ',open(md).read())[1:]:
        title=block.split('\n',1)[0]
        cap='\n'.join(l[2:] if l.startswith('> ') else '' for l in block.split('\n') if l.startswith('>')).strip()
        tags=re.search(r'`(#[^`]+)`',block); fc=re.search(r'\*\*Первый комментари[^*]*\*\*:? ?«?(.+?)»?\n',block)
        chk=re.search(r'\*\*Чек:\*\*(.*?)(?:\n\n|\Z)',block,re.S)
        out[title]=(cap,fc.group(1) if fc else '',tags.group(1) if tags else '',chk.group(1).strip().replace('\n',' ') if chk else '')
    return out
